using System;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering.HighDefinition;
using Object = UnityEngine.Object;

namespace Gamex.EditorTools
{
    /// <summary>
    /// The player's torch in the forest rig (N1, build/issues/N1-night.md). <see cref="PlayerFlashlight"/> owns the photometry
    /// (lumens, cone, colour, range, lag); this sets what only HDRP knows (shadow resolution and update mode, softness, the
    /// volumetric beam) and writes the beam pattern, generated by code, as an asset the light references, so the saved scene,
    /// edit-mode captures, play mode and the player all use the same texture.
    /// </summary>
    public static class ForestFlashlight
    {
        public const string ObjectName = "Flashlight";
        public const string CookiePath = ForestPaths.LightingFolder + "/FlashlightBeamPattern.asset";
        public const int CookieSize = 256;

        /// <summary>Where the torch is held, in the camera pivot's space: in the right hand, below the eye, in front of the body.</summary>
        public static readonly Vector3 HandPosition = new Vector3(0.22f, -0.30f, 0.25f);

        /// <summary>The beam is aimed at the centre of the view this far ahead, so the hot spot sits where the player looks.</summary>
        public const float AimDistance = 12f;

        /// <summary>
        /// Shadow map of the torch, in pixels a side, re-rendered every frame (the light moves with the view; a cached map would
        /// trail it). Chosen in N1 step 3 by measurement in the player (build/issues/N1-night.md, section 4).
        /// </summary>
        public const int ShadowResolution = 1024;
        public const ShadowUpdateMode ShadowUpdate = ShadowUpdateMode.EveryFrame;

        /// <summary>
        /// How strongly the beam lights the mist, against the physical 1. At 1 the light, inside the mist at the player's hip, filled
        /// the frame with a white cone (the in-scattered light grows as 1 / d^2 toward the source); at 0.04 the beam shows as a shaft
        /// from the hand and a haze ahead and the lit ground stays readable through it (build/issues/N1-night.md, section 3).
        /// </summary>
        public const float VolumetricDimmer = 0.04f;

        /// <summary>The LED's radius: it softens the shadows a little where the pipeline's filtering allows (PCSS).</summary>
        public const float ShapeRadius = 0.015f;

        /// <summary>
        /// Adds the torch to the camera pivot of a player rig: a spot light with its HDRP data, the beam pattern and the
        /// <see cref="PlayerFlashlight"/> component, which starts switched on.
        /// </summary>
        public static PlayerFlashlight Build(Transform cameraPivot)
        {
            if (cameraPivot == null) throw new ArgumentNullException(nameof(cameraPivot));

            var holder = new GameObject(ObjectName);
            holder.transform.SetParent(cameraPivot, false);
            holder.transform.localPosition = HandPosition;
            holder.transform.localRotation = Quaternion.LookRotation(new Vector3(0f, 0f, AimDistance) - HandPosition, Vector3.up);

            // Adding the HDRP component also adds the Light it requires.
            var data = holder.AddComponent<HDAdditionalLightData>();
            var light = holder.GetComponent<Light>();
            light.type = LightType.Spot;
            light.lightmapBakeType = LightmapBakeType.Realtime;
            light.cookie = WriteCookie();

            var torch = holder.AddComponent<PlayerFlashlight>();
            torch.ApplyPhotometry();
            Configure(data);
            Debug.Log($"Forest flashlight: {torch.Lumens:0} lm, peak {torch.PeakCandela:0} cd, cone {torch.InnerConeDegrees:0} / {torch.OuterConeDegrees:0} degrees, " +
                $"range {torch.Range:0} m, shadows {ShadowResolution} px {ShadowUpdate}, volumetric dimmer {VolumetricDimmer}, lag {torch.LagSeconds:0.00} s.");
            return torch;
        }

        /// <summary>The HDRP side of the torch. A script-created light starts with 512-pixel shadows and default biases.</summary>
        public static void Configure(HDAdditionalLightData data)
        {
            if (data == null) throw new ArgumentNullException(nameof(data));
            data.SetShadowResolutionOverride(true);
            data.SetShadowResolution(ShadowResolution);
            data.shadowUpdateMode = ShadowUpdate;
            data.shadowNearPlane = 0.1f;
            data.shadowDimmer = 1f;
            data.normalBias = 0.75f;
            data.slopeBias = 0.5f;
            data.GetComponent<Light>().shapeRadius = ShapeRadius;
            // A light at the eye sees almost none of the contacts its own screen-space contact shadows would add.
            data.useContactShadow.useOverride = true;
            data.useContactShadow.@override = false;
            data.affectsVolumetric = true;
            data.volumetricDimmer = VolumetricDimmer;
            data.volumetricShadowDimmer = 1f;
            data.lightDimmer = 1f;
        }

        /// <summary>The beam pattern as a texture asset in ForestData/Lighting, rewritten in place (its GUID kept) on every build.</summary>
        public static Texture2D WriteCookie()
        {
            ForestTerrain.EnsureAssetFolder(ForestPaths.LightingFolder);
            Texture2D generated = PlayerFlashlight.CreateCookie(CookieSize);
            var existing = AssetDatabase.LoadAssetAtPath<Texture2D>(CookiePath);
            if (existing != null && existing.width == CookieSize && existing.height == CookieSize && existing.format == generated.format
                && existing.mipmapCount == generated.mipmapCount && existing.isReadable)
            {
                existing.SetPixels32(generated.GetPixels32());
                existing.Apply(true, false);
                existing.wrapMode = TextureWrapMode.Clamp;
                existing.filterMode = FilterMode.Bilinear;
                Object.DestroyImmediate(generated);
                EditorUtility.SetDirty(existing);
                AssetDatabase.SaveAssetIfDirty(existing);
                return existing;
            }
            if (existing != null)
                AssetDatabase.DeleteAsset(CookiePath);
            AssetDatabase.CreateAsset(generated, CookiePath);
            return generated;
        }

        /// <summary>The torch of a player rig, or null.</summary>
        public static PlayerFlashlight Find(Component playerPart)
        {
            if (playerPart == null)
                return null;
            Transform root = playerPart.transform.root;
            return root.GetComponentInChildren<PlayerFlashlight>(true);
        }

        /// <summary>
        /// For edit-mode captures, which render from a camera of their own: while the returned object lives, a copy of the
        /// player's torch rides on <paramref name="captureCamera"/> at the hand's pose (switched on or off), and the player's own
        /// torch, which stands at the spawn, is dark. Without a torch in the scene the capture has none either.
        /// </summary>
        public static CaptureTorch HoldForCapture(Camera playerCamera, Camera captureCamera, bool on)
        {
            return new CaptureTorch(Find(playerCamera), captureCamera, on);
        }

        public sealed class CaptureTorch : IDisposable
        {
            readonly Light original;
            readonly bool originalEnabled;
            GameObject copy;

            /// <summary>"on", "off", or "none" when the scene's player has no torch.</summary>
            public string State { get; }

            internal CaptureTorch(PlayerFlashlight torch, Camera captureCamera, bool on)
            {
                if (torch == null || captureCamera == null)
                {
                    State = "none";
                    return;
                }
                // The scene's own component is read through GetComponent: its properties would initialise it in edit mode.
                original = torch.GetComponent<Light>();
                originalEnabled = original.enabled;
                original.enabled = false;
                State = on ? "on" : "off";
                if (!on)
                    return;

                copy = Object.Instantiate(torch.gameObject, captureCamera.transform, false);
                copy.name = ObjectName + " (capture)";
                copy.hideFlags = HideFlags.HideAndDontSave;
                copy.transform.localPosition = torch.transform.localPosition;
                copy.transform.localRotation = torch.transform.localRotation;
                foreach (PlayerFlashlight behaviour in copy.GetComponents<PlayerFlashlight>())
                    Object.DestroyImmediate(behaviour);
                copy.GetComponent<Light>().enabled = true;
            }

            public void Dispose()
            {
                if (copy != null)
                    Object.DestroyImmediate(copy);
                copy = null;
                if (original != null)
                    original.enabled = originalEnabled;
            }
        }
    }
}
